from pathlib import Path
import html
R=Path(__file__).resolve().parents[1]/'docs/econometrics/v2'
# Each note supplies a module-specific derivation and a worked reasoning task.
notes=[
('均值差的识别分解','在处理组结果均值中加上再减去E[Y(0)|D=1]，第一部分成为E[Y(1)−Y(0)|D=1]，第二部分成为未处理潜在结果的组间差。观测均值差因此只在选择偏差为零时等于ATT。随机分配识别分配效应；存在不依从时，实际接受处理的比较重新带有选择。','若处理者在未处理时本来比对照者少挣2，而观测差为3，ATT=5。选择偏差可以向下，不能默认所有观察性差异都夸大效应。'),
('从目标函数到正规方程','令S(b)=(y−Xb)′(y−Xb)，梯度为−2X′(y−Xb)，Hessian为2X′X。满列秩使目标严格凸，驻点是唯一极小值，故b=(X′X)⁻¹X′y。该结论只用代数，不需要随机误差假设。含截距时e与常数及拟合值正交，由y−ȳ=(ŷ−ȳ)+e得到SST=SSR+SSE。','若E[u|X]=0，则E[b|X]=β；若只有E[xu]=0，通常只能在相应LLN条件下证明一致性，不能直接推出条件无偏。'),
('分块正规方程证明FWL','写y=xb+Zc+e。第二组正规方程给c=(Z′Z)⁻¹Z′(y−xb)，代回第一组得到x′M_Z(y−xb)=0。因此b=(x′M_Zx)⁻¹x′M_Zy。M_Z对称幂等使残差化后的交叉积等于原式。要求Z满秩且x残差仍有变异。','只残差化y时分子仍为x′M_Zy，分母却是x′x而非x′M_Zx，因此通常得到不同系数。'),
('投影的存在与唯一性','满列秩保证X′X正定。直接相乘得P²=P，转置得P′=P，因此P与I−P的乘积为零。对任意候选Xa，y−Xa=e+(ŷ−Xa)，两项正交，平方范数等于两项平方范数之和，所以ŷ最近。','秩不足时系数可以不唯一，但向列空间的正交投影仍唯一。可用QR或SVD求解，不能把软件返回某个系数向量解释为所有系数均已识别。'),
('函数形式与不确定性','交互模型的条件斜率为β1+β3z，其方差为Var(b1)+z²Var(b3)+2zCov(b1,b3)。因此只看交互系数的显著性不能判断某个z处效应是否显著。对数结果模型满足E[Y|X]=exp(Xβ)E[exp(u)|X]，直接指数化遗漏第二项。','取Var(b1)=.04、Var(b3)=.01、Cov=−.01、z=2，斜率方差=.04，标准误=.2。忽略协方差会得到错误区间。'),
('精确检验与Wald的联系','正态同方差模型下，限制与非限制残差平方和之差除以q，再除以非限制残差方差，得到F(q,n−k)。同一模型下W=qF，但用估计误差方差构造的W有限样本并非精确χ²。异方差稳健Wald依赖渐近正态及协方差一致性。','一个限制下W=t²；两侧t检验与相应F检验一致。多个限制下需检查R满行秩，否则直接求逆失效。'),
('一致性的逐步论证','由b−β=Qhat⁻¹ n⁻¹Σxᵢuᵢ出发。独立同分布、E||xx′||有限和E||xu||有限保证样本矩收敛；Q正定保证其逆连续。总体正交E[xu]=0于是给b→pβ。没有正交时极限是β+Q⁻¹E[xu]，这是伪真目标与结构真值的区别。','实验固定样本量分别取50、200、800，每个设定重复至少1000次，报告偏差与RMSE。把内生相关系数从0改为.5后，方差下降而偏差不消失，体现识别与精度的区别。'),
('从得分CLT到可行区间','令sᵢ=xᵢuᵢ。独立同分布、E[s]=0且二阶矩有限时，多元CLT给n⁻¹/²Σsᵢ→dN(0,S)。再以Qhat→pQ及Slutsky得到√n(b−β)→dN(0,Q⁻¹SQ⁻¹)。若Vhat一致估计此极限方差，系数标准误应取sqrt(Vhat_jj/n)，不是sqrt(Vhat_jj)。','若软件直接输出Covhat(b)，其中已经含1/n，再除一次会使区间过窄。蒙特卡洛同时比较正确区间与重复除n区间的覆盖率。'),
('残差夹心的一致性','不可观测的u²需用e²替代。由eᵢ=uᵢ−xᵢ′(b−β)，展开eᵢ²−uᵢ²包含一个线性误差项与一个二次误差项。在固定维数、适当高阶矩、b一致及LLN下，其加权平均为op(1)，因此Shat=n⁻¹Σxx′e²一致。只引用Slutsky不足以证明这一步。','HC1与HC0仅相差n/(n−k)，固定k时差异渐近消失。高杠杆下残差可能系统性低估误差波动，需比较HC2/HC3并检查设计。'),
('为何按组汇总得分','设组g得分s_g=Σ_i∈g xᵢuᵢ。独立信息单位是组，meat应使用Σ_g shat_g shat_g′，展开后包含同组不同观测的交叉项。普通HC只保留对角项。组数增长且没有单组支配、组间独立等条件支持常用聚类渐近论证。','组数固定而每组人数增长不自动满足通常的大组数近似。应报告组数、组规模分布和处理分配层级，少组情形考虑与设计相符的随机化推断或适当wild cluster bootstrap。'),
('Delta方法的泰勒余项','若g可微，g(b)−g(β)=G′(b−β)+r，其中r=o(||b−β||)。乘√n后余项为op(1)，故极限方差G′VG。若G=0，一阶结论退化，例如β=0且g(b)=b²，需改看n b²，其极限为缩放χ²而非普通正态。','对exp(β)可将β置信区间整体指数化，保持正值和非对称性；这与直接以Delta标准误构造对称区间是不同程序。'),
('HAC是依赖得分的长期方差','平稳弱依赖得分的长期方差S=Γ0+Σ_l≥1(Γl+Γl′)。HAC用有限滞后及核权重估计此和，并与设计矩阵逆组成夹心。带宽随n增长但相对n足够慢及适当依赖衰减是常见一致性条件。VIF和杠杆诊断不提供这些条件。','将同一序列随机打乱会破坏时间依赖，不能作为原序列有效性的验证。比较带宽是敏感性检查，不应选出使p值最小的设定。'),
('两种内生性偏差的推导','遗漏a时，Cov(x,y)/Var(x)=β+γCov(x,a)/Var(x)，条件是Cov(x,u)=0。经典测量x*=x+v且v与x,u不相关时，Cov(x*,y)=βVar(x)，Var(x*)=Var(x)+Var(v)，比值产生衰减。两种公式依赖不同生成机制。','同时存在遗漏变量与测量误差时，不能把两个偏差机械相加；先写完整协方差再求极限。真实工资回归只能给条件关联，不能用模拟真值为其因果解释背书。'),
('调整集合与目标效应','后门调整用Σ_x E[Y|D=d,X=x]P(X=x)构造干预均值，需要一致性、条件交换性与正值性。控制中介得到的条件比较一般不等于自然直接效应；后者涉及跨潜在状态对象及更强识别条件。图中箭头应来自时间顺序和制度知识。','对D→M←U→Y，控制M打开D与U的路径。即使M显著预测Y，加入它也可能制造偏差。先画路径再判断，而不是按拟合优度筛控制。'),
('Wald比值的来源','二元工具下约化式差为ΔY，第一阶段差为ΔD。随机工具、排他性和单调性使永远处理者与从不处理者对约化式差的贡献抵消，只剩依从者比例乘其平均效应；第一阶段差正是依从者比例。两者相除得到LATE。','ΔY=.6、ΔD=.2得到3；若ΔD改为.02，比值为30，但分母抽样误差可能主导，必须进入弱识别分析，不能只报告更大的效果。'),
('一般GMM方差与最优权重','令D=E[∂g_i(θ0)/∂θ′]，S=Var(g_i)。一阶条件在真值展开得到√n(θhat−θ0)=−(D′WD)⁻¹D′W√n gbar(θ0)+op(1)。因此方差为(D′WD)⁻¹D′WSWD(D′WD)⁻¹；W=S⁻¹时化为(D′S⁻¹D)⁻¹。要求识别、样本矩一致收敛、导数控制及相应CLT。','L=3、K=2且满秩时J自由度为1。错误矩条件下参数仍可能使部分矩接近零，因此J不拒绝不是外生性的证书。'),
('2SLS的矩阵与方差','将X投影为Xhat=P_ZX，再回归得到(X′P_ZX)⁻¹X′P_Zy。结构残差应为e=y−Xb。独立异方差下系数协方差为A⁻¹X′P_Z diag(e²)P_ZX A⁻¹，其中A=X′P_ZX。手工第二阶段用y−Xhat b会误估结构误差。','若工具矩阵含外生控制而结构式遗漏同一控制，模型目标发生变化。比较手工点估计与专用IV估计应固定样本、工具及截距处理。'),
('AR检验反演','对每个候选β0，构造r=Y−β0D，并回归于工具和外生控制。检验排除工具的系数联合为零；对控制残差化后，这等价于检验相应工具矩。保留不被拒绝的β0形成置信集。有效性仍依赖工具外生与适当误差推断，但无需强第一阶段。','置信集可能不连通或无界，这是识别信息不足的表现。实现时扩大搜索网格并检查边界，不能把有限网格截断误报为有界区间。'),
('从似然曲率到渐近正态','定义平均得分sbar(β)，内点解满足sbar(b)=0。在β0展开：0=sbar(β0)−Atilde(b−β0)，故√n(b−β0)=Atilde⁻¹√n sbar(β0)。若Atilde→pA、得分CLT方差为B，则极限方差A⁻¹BA⁻¹。正确设定和可交换微分积分等条件下A=B。','误设时目标是最大化期望对数似然的伪真参数。稳健方差只刻画该目标附近的波动，不恢复结构真值。Logit完全分离时有限极大值不存在，数值收敛提示不能替代存在性检查。'),
('AME的完整梯度','Logit中p_i=Λ(x_i′β)。无交互的连续变量效应a_i=β_j p_i(1−p_i)，其梯度为单位向量e_j乘p_i(1−p_i)，加β_j p_i(1−p_i)(1−2p_i)x_i。平均梯度与系数协方差结合给固定设计Delta方差。','二元处理必须分别设D=1和0，保留其他变量并平均预测差。含交互项时还要同时更新交互列，不能只替换D这一列。'),
('PPML为何允许分布误设','Poisson准得分为x(Y−exp(x′β))。只要条件均值正确，条件期望得分为零，即使Var(Y|X)不等于均值也可建立一致性；需使用夹心方差。若均值错，过度离散修正并不能恢复目标。非负连续Y可用同一准得分，但不能宣称服从Poisson。','零值可直接进入水平结果PPML，无须任意加1取对数。比较对数OLS与PPML时，两者目标和误差结构不同，不能只按R²选择。'),
('分位数与选择应分别识别','分位数回归最小化Σρτ(y−x′β)，ρτ(u)=u(τ−1{u<0})。条件密度在目标分位附近及设计条件影响渐近方差。它估计条件分位，不自动描述某一固定个体的处理效应。样本选择模型则需单独建模被观察概率及结果误差依赖。','Heckman两步的第二阶段加入估计逆Mills比会产生生成回归量不确定性，普通OLS标准误不足；排除限制的可信性应独立讨论，不能把正态函数形式当作唯一实质依据。'),
('条件独立到识别公式','一致性给D=d时Y=Y(d)，交换性给E[Y(d)|X]=E[Y(d)|D=d,X]，合并得到E[Y(d)]=E_X E[Y|D=d,X]。重叠确保每个目标X区域都能观察到相应处理状态。随机化是设计保证，观察性条件独立是实质假设。','若某协变量区域只有处理者，其对照潜在结果不能从该区域数据直接估计。删去该区域改变目标总体，须重新定义估计量及外推范围。'),
('双重稳健的条件期望证明','以m_d和e表示拟合函数。若e正确，条件于X时E[D(Y−m1)/e]=μ1−m1，对照项相似，故AIPW期望为μ1−μ0。若m_d=μ_d，两个残差项条件期望为零，即使e误设仍成立。两者都错时余项由两类误差乘积决定。','双重稳健是一致性性质，不自动给根号n推断。交叉拟合下还需适当L2误差乘积为op(n⁻¹/²)、重叠及矩界。极端权重会使理论近似与数值稳定性恶化。'),
('组内变换的识别条件','对y_it=α_i+x_it′β+u_it减个体均值，得到去均值回归。固定T、大N时，严格外生E[u_it|x_i1,…,x_iT,α_i]=0是常见充分条件；仅当期外生不足以消除去均值后的相关。时间不变变量被消去，不能从组内变异识别其系数。','RE还要求个体效应与解释变量适当不相关。Hausman比较依赖两种估计量在原假设下的有效性与协方差条件，不应作为机械模型选择开关。'),
('差分矩的构造','差分后Δu_it=u_it−u_i,t−1，Δy_i,t−1含u_i,t−1，故仍内生。若水平误差无序列相关及初始条件适当，t−2及更早y与Δu_it正交。将各期有效工具堆叠为Z_i，以E[Z_i′Δu_i]=0做GMM。','差分残差出现一阶相关并不意外，因为共享相邻水平误差；二阶相关威胁常用矩。报告工具数量并限制滞后，不以接近1的Hansen p值自动认定模型优秀。'),
('DID识别的潜在结果推导','目标是E[Y1(1)−Y1(0)|D=1]。无预期使处理前观测等于Y0(0)；平行趋势令E[Y1(0)−Y0(0)|D=1]等于对照组变化。把后者代入未处理反事实，得到两组两期差分。还需一致性、无相关溢出及适当样本组成条件。','两组前期水平可以不同。只有两个时期时无法用数据检验前趋势，不能将FE回归中的显著处理交互项当作平行趋势证据。'),
('事件时间系数如何解读','省略−1期后，系数反映相对该期的处理组对照组差异变化。政策前联合检验应利用完整协方差，而非逐项查看p值。尾部合并改变系数的加权对象；不平衡面板也可能改变不同事件时间的样本构成。','同一组真实效应恒为2，但基期受预期影响为1，则相对基期系数可能仅为1。应先论证无预期窗口，再选择基期并说明样本支持。'),
('组别时间ATT与聚合','对队列g与时期t，使用g−1作基期并选未处理对照，在相应平行趋势下识别ATT(g,t)。事件时间k的效应由满足t−g=k的单元加权平均得到。不同k可用队列不同，因此路径变化可能混合效应变化与构成变化。','可固定共同支持队列再比较动态路径，并同时报告原聚合。简化均值差实验不含完整干扰函数或条件双重稳健推断，正式研究需使用对应估计程序。'),
('凸权重优化与推断边界','经典问题在单纯形上最小化政策前加权距离。非负和和为1限制外推，供体凸包外无法精确拟合。政策后缺口能否解释为因果效应取决于无处理结果关系在政策后仍成立、供体未受干预及无其他处理单位特有冲击。','安慰剂比较应重估每个假处理单位并检查其前期拟合。若真实处理分配没有可交换性，排名不能无条件解释为精确随机化p值。'),
('局部线性与模糊断点','以r=R−c，在带宽内分别拟合左右截距与斜率，并用核权重最小化平方误差。截距差估计阈值跳跃，而全样本均值差混合了运行变量分布差异。模糊RDD对结果跳跃和处理跳跃取比值，需要局部第一阶段非零。','若阈值同时改变另一项政策，结果跳跃可能属于组合干预。密度连续或协变量连续不能排除此类制度威胁，必须核查阈值规则。'),
('偏差修正为何改变标准误','局部线性截距的平滑偏差通常随h²变化，方差数量级为1/(nh)。按均方误差选择的带宽使偏差相对标准误可能不可忽略。偏差修正使用额外局部拟合估计主导偏差；修正量本身随机，区间需计入其方差与协方差。','只减去一个偏差估计再沿用原标准误不是完整稳健偏差修正。应报告主带宽、偏差带宽、核、阶数、有效样本及质量点处理。'),
('协整与误差修正的关系','两个I(1)序列若y−θx平稳，则长期偏离可进入差分方程作为调整项。估计长期关系后的残差具有估计引起的特殊分布，残差单位根检验需专用临界值。若不存在协整，直接把水平变量放入普通回归可能得到伪显著。','先确定常数趋势项及滞后策略，再报告检验。不能用不拒绝单位根证明一定I(1)，也不能用单条平稳残差图替代协整检验。'),
('检验族与敏感性参数','BH程序排序全部预先定义的m个p值，找最大k使p_(k)≤kq/m并拒绝前k项。在独立或适当正依赖条件下控制FDR。敏感性分析则应明确未观测偏差参数及其标度，展示结论在何种参数范围改变。','若先筛出最小的5个p值再以m=5校正，会漏掉筛选过程。Oster分析需报告Rmax与比例选择假设，不能只给一个看似稳健的校正系数。'),
('正交性与交叉拟合','令V=D−m0(X)，U=Y−l0(X)−θ0V。在识别条件下E[VU]=0。扰动l方向时导数为−E[Vh(X)]=0；扰动m方向时涉及E[U|X]与E[V|X]，均为零。因此干扰估计误差的一阶影响消失，余项通常包含乘积。','每折模型只能在训练样本拟合，留出折生成残差，然后合并所有留出得分求θ。数据预处理、特征选择也应在训练折内完成；相关组须整体分折。'),
('复现项目的可审计交付','选择一个有公开数据与代码的研究，先登记论文版本、数据许可、下载日期、文件校验值和目标表图。建立原始数据到分析样本的流转表，对每次筛选记录样本数。主结果逐项对照系数、SE、N、固定效应与聚类。差异要追溯而非调参消除。','评分建议：数据与环境可追溯20分，基准表图重建25分，识别审查25分，稳健性及差异解释20分，单入口复现10分。模拟不能代替真实论文复现，未完成项目应保留明确状态。')
]
assert len(notes)==36
for i,(title,theory,exercise) in enumerate(notes,1):
 p=R/'modules'/f'M{i:02}.html';s=p.read_text(encoding='utf-8')
 import re
 s=re.sub(r'<section class="paper" id="deepening">.*?</section>','',s,flags=re.S)
 block=f'<section class="paper" id="deepening"><h2>进阶讲义 · {html.escape(title)}</h2><h3>推导与成立条件</h3><p>{html.escape(theory)}</p><h3>工作例题与研究判断</h3><p>{html.escape(exercise)}</p><h3>实验报告要求</h3><p>运行本页实验前，写出目标参数、数据生成机制和所用协方差。保存基准输出，再改变一个与本课结论直接相关的条件，比较估计值、标准误或覆盖率。解释变化来自识别、有限样本波动还是推断方法。模拟结果仅用于检验指定机制；若脚本未实现某项高级推断，应明确记录并参照方法文档补做，不能把输出标签当作实现证据。</p></section>'
 s=s.replace('<section class="paper" id="s3">',block+'<section class="paper" id="s3">',1)
 if i==1 and '<div class='+chr(34)+'diagram'+chr(34)+'>' in s:
  start=s.index('<div class="diagram">');end=s.index('</svg></div>',start)+len('</svg></div>')
  s=s[:start]+'<div class="formula">观测均值差 = ATT + 未处理潜在结果的选择偏差</div>'+s[end:]
  s=s.replace('<h2>4 · 可复现实验：Stata与Python</h2>','<h2>4 · 后续OLS实验预览：Stata与Python</h2><p>本节脚本演示投影与残差化，对应M02—M04；它没有生成潜在结果，不能用来验证本课的ATT分解。本课先完成均值差分解手算，再在M23的随机处理设计中比较反事实目标。</p>')
 p.write_text(s,encoding='utf-8')
